  "Issued while BTS was unreachable": "Emitido mientras BTS no estaba disponible",
  "You can give this copy to your customer: it says \"Pending of BTS authorization\". We send it to BTS automatically when it is back; this page updates by itself.": "Puede entregar esta copia a su cliente: dice \"Pendiente de autorización de BTS\". La enviamos a BTS automáticamente cuando vuelva; esta página se actualiza sola.",
  "BTS could not be reached, so this sale was reissued as a contingency document. This one will never be sent.": "No se pudo conectar con BTS, así que esta venta se volvió a emitir como documento de contingencia. Este nunca se enviará.",
