  "Choose your QuickBooks tax code for each GST rate, and QuickBooks books the tax. Until then, lines are sent with GST included so totals always match your e-invoices.": "Elija su código de impuesto de QuickBooks para cada tasa de GST, y QuickBooks registra el impuesto. Mientras tanto, las líneas se envían con el GST incluido para que los totales coincidan siempre con sus facturas electrónicas.",
