  "More connections": "Más conexiones",
  "Xero, Sage and others can connect today through the API and webhooks (Settings → Developers). Tell us which you need next.": "Xero, Sage y otros se pueden conectar hoy mediante la API y los webhooks (Ajustes → Desarrolladores). Díganos cuál necesita.",
  "Pricing": "Precios",
  "Electronic tax documents for Belize": "Documentos tributarios electrónicos para Belice",
  "Privacy": "Privacidad",
  "QuickBooks and other integrations": "QuickBooks y otras integraciones",
  "What counts as a document?": "¿Qué cuenta como documento?",
  "Every tax invoice, receipt, credit or debit note issued in the BTS production environment. Documents in the test environment are always free and unlimited.": "Cada factura, recibo, nota de crédito o débito emitido en el entorno de producción de BTS. Los documentos del entorno de pruebas son siempre gratuitos e ilimitados.",
  "Is there a free trial?": "¿Hay prueba gratuita?",
  "Yes: every new business gets {n} days of the Business plan, with no card needed.": "Sí: cada negocio nuevo recibe {n} días del plan Business, sin tarjeta.",
  "Can I change plans?": "¿Puedo cambiar de plan?",
  "Any time, in Settings → Plan. Upgrades apply at once; a downgrade applies at the end of the month.": "Cuando quiera, en Configuración → Plan. Subir aplica de inmediato; bajar aplica al final del mes.",
  "How do I pay?": "¿Cómo pago?",
  "Each month is invoiced at the start (a BTS e-invoice, of course) and due in 14 days. GST is added at 12.5%.": "Cada mes se factura al inicio (con una factura electrónica de BTS, claro) y vence en 14 días. Se agrega el GST de 12.5%.",
  "What if a payment is late?": "¿Y si un pago se atrasa?",
  "After 14 days overdue, issuing new documents pauses until it is paid. Your documents always stay available to view, print and download.": "Con más de 14 días de atraso, la emisión de documentos nuevos se pausa hasta que se pague. Sus documentos siempre siguen disponibles para ver, imprimir y descargar.",
  "Simple plans for Belizean businesses.": "Planes sencillos para negocios beliceños.",
  "Issue BTS-authorized invoices and receipts, sell online and keep working through outages. Start free for {n} days.": "Emita facturas y recibos autorizados por BTS, venda en línea y siga trabajando aunque BTS falle. Empiece gratis por {n} días.",
  "Contingency mode when BTS is down": "Modo de contingencia cuando BTS no responde",
  "Start free": "Empezar gratis",
  "Questions": "Preguntas",
  "the company that runs this service": "la empresa que opera este servicio",
