  "Automatic reminders": "Recordatorios automáticos",
  "Customers with an email address get a reminder with the invoice attached and a link to pay. Each reminder is sent once per invoice.": "Los clientes con correo electrónico reciben un recordatorio con la factura adjunta y un enlace para pagar. Cada recordatorio se envía una sola vez por factura.",
