  "When to send them (up to 6):": "Cuándo enviarlos (hasta 6):",
  "Paying online": "Pagos en línea",
  "Invoices you email include a “Pay online” link. Payments go through {provider} and are recorded on the invoice by themselves.": "Las facturas que envía por correo incluyen un enlace “Pagar en línea”. Los pagos pasan por {provider} y se registran solos en la factura.",
