  "Belize Bank cards": "Tarjetas de Belize Bank",
  "Connect Belize Bank, E-Kyash or PayPal in Settings → Online store to let customers pay invoices online.": "Conecte Belize Bank, E-Kyash o PayPal en Configuración → Tienda en línea para que los clientes paguen facturas en línea.",
