  "A spreadsheet saved as CSV, one customer per row: Name is needed; TIN, Email, Phone, Street, City and District are optional. Customers with the same TIN or email are updated.": "Una hoja de cálculo guardada como CSV, un cliente por fila: se necesita Nombre (Name); TIN, Email, Phone, Street, City y District son opcionales. Los clientes con el mismo TIN o correo se actualizan.",
