  "Suspended": "Suspendido",
  "Suspended since {date}": "Suspendido desde {date}",
  "No one can sign in; its tills, API keys and online store are refused. Reason: {reason}": "Nadie puede iniciar sesión; se rechazan sus cajas, claves de API y tienda en línea. Motivo: {reason}",
  "{n} pending": "{n} pendientes",
  "{n} for more than 15 minutes": "{n} desde hace más de 15 minutos",
  "{n} issued offline, to send": "{n} emitidos sin conexión, por enviar",
  "issuing offline now": "emitiendo sin conexión ahora",
  "{n} documents settled with BTS": "{n} documentos resueltos con el BTS",
  "Nothing could be settled yet; BTS may still be unreachable.": "Todavía no se pudo resolver nada; puede que el BTS siga sin responder.",
  "Send now": "Enviar ahora",
  "People": "Personas",
  "For someone locked out. A password link only ever goes to the person’s own email; you never see it.": "Para alguien que no puede entrar. El enlace de contraseña solo va al correo de la persona; usted nunca lo ve.",
  "Two-step": "Dos pasos",
  "No email on this account: an owner or admin of the business can set a temporary password": "Esta cuenta no tiene correo: un propietario o administrador del negocio puede poner una contraseña temporal",
  "Password link emailed to {email}": "Enlace de contraseña enviado a {email}",
  "Email a password link": "Enviar enlace de contraseña",
  "Turn off two-step": "Desactivar dos pasos",
  "Suspend this business": "Suspender este negocio",
  "For fraud, abuse or a legal order. No one can sign in, its tills, API keys and store stop, and its owners are told why. Documents already on their way to BTS still finish.": "Por fraude, abuso u orden legal. Nadie puede iniciar sesión, se detienen sus cajas, claves de API y tienda, y se les dice el motivo a sus propietarios. Los documentos que ya van hacia el BTS terminan igual.",
  "Suspend": "Suspender",
  "{name} is suspended": "{name} está suspendido",
  "{name} is active again": "{name} está activo de nuevo",
  "Two-step sign-in is off for {name}": "El inicio de sesión en dos pasos está desactivado para {name}",
  "Suspend {name}?": "¿Suspender {name}?",
  "Reactivate {name}?": "¿Reactivar {name}?",
  "Turn off two-step sign-in for {name}?": "¿Desactivar el inicio de sesión en dos pasos para {name}?",
  "Its owners are emailed the reason, and it appears in the business’s own activity log.": "Se envía el motivo por correo a sus propietarios y aparece en el registro de actividad del negocio.",
  "Its people can sign in again and its tills, API keys and store work as before. Its owners are emailed.": "Su gente puede volver a iniciar sesión y sus cajas, claves de API y tienda funcionan como antes. Se avisa por correo a sus propietarios.",
  "Only once you are sure it is them (a lost or replaced phone). They are signed out everywhere, emailed, and set it up again after signing in with their password.": "Solo cuando esté seguro de que es la persona (un teléfono perdido o cambiado). Se cierra su sesión en todas partes, se le avisa por correo y lo configura de nuevo al entrar con su contraseña.",
  "How you confirmed who they are.": "Cómo confirmó quién es.",
  "Notice posted to every business": "Aviso publicado para todos los negocios",
  "Notice ended": "Aviso terminado",
  "A line at the top of every business’s app while it lasts: maintenance, a BTS outage, news. Each person can dismiss it.": "Una línea arriba en la aplicación de cada negocio mientras dure: mantenimiento, una caída del BTS, noticias. Cada persona puede descartarla.",
  "Post a notice": "Publicar un aviso",
  "Maintenance tonight from 11 pm to midnight.": "Mantenimiento esta noche de 11 pm a medianoche.",
  "In Spanish": "En español",
  "Optional: shown to people using the app in Spanish.": "Opcional: se muestra a quienes usan la aplicación en español.",
  "Information": "Información",
  "Warning": "Advertencia",
  "Optional: it stays until you end it.": "Opcional: se queda hasta que usted lo termine.",
  "Posting…": "Publicando…",
  "Post to every business": "Publicar para todos los negocios",
