  "{amount} of work to invoice for 1 customer": "{amount} de trabajo por facturar a 1 cliente",
  "{amount} of work to invoice for {n} customers": "{amount} de trabajo por facturar a {n} clientes",
  "What you charge for, by the hour, the day or the job, with its GST. They fill in the rate on invoices, quotes and logged work.": "Lo que cobra, por hora, por día o por trabajo, con su GST. Llenan la tarifa en facturas, cotizaciones y trabajo registrado.",
  "What you sell": "Lo que vende",
  "Services: no stock or online store products; time and jobs to invoice instead. You can change it any time; nothing is lost.": "Servicios: sin inventario ni productos de tienda en línea; en su lugar, tiempo y trabajos por facturar. Puede cambiarlo cuando quiera; no se pierde nada.",
  "Both": "Ambos",
  "What do you sell?": "¿Qué vende?",
  "For consultants, repairs, salons, clinics and the like: invoice by the hour or the job, without stock.": "Para consultores, reparaciones, salones, clínicas y similares: facture por hora o por trabajo, sin inventario.",
  "For shops: stock, the counter and an online store.": "Para tiendas: inventario, la caja y una tienda en línea.",
  "Everything: products with stock, and services by the hour or the job.": "Todo: productos con inventario y servicios por hora o por trabajo.",
  "Removed": "Eliminado",
  "Log the work you do for each customer as you go, by the hour or by the job, then invoice it in one go.": "Registre el trabajo que hace para cada cliente a medida que avanza, por hora o por trabajo, y luego facture todo de una vez.",
